# Reconstruction of the four-way leading-edge intersection described in manuscript section 2.3.
# New reproducibility script; NOT claimed to be the historical selection script.
# Input generated by original script 25. No fgsea rerun and no DE reanalysis.
input <- "Hallmark_leadingEdge_genes_detalle.csv"
if (!file.exists(input)) stop("Missing input: ", input)
x <- read.csv(input, stringsAsFactors = FALSE, check.names = FALSE)
needed <- c("pathway","gene","leadingEdge_GSE108022","leadingEdge_GSE28511")
if (!all(needed %in% names(x))) stop("Missing required columns: ", paste(setdiff(needed,names(x)),collapse=", "))
if (anyNA(x[,needed])) stop("Missing values in required columns")
if (!is.logical(x$leadingEdge_GSE108022) || !is.logical(x$leadingEdge_GSE28511)) stop("Leading-edge flags must be logical")
p <- c("HALLMARK_OXIDATIVE_PHOSPHORYLATION","HALLMARK_FATTY_ACID_METABOLISM")
if (!all(p %in% x$pathway)) stop("Missing metabolic Hallmark(s)")
shared <- lapply(p, function(pathway) {
  z <- x[x$pathway == pathway & x$leadingEdge_GSE108022 & x$leadingEdge_GSE28511, "gene"]
  if (anyNA(z) || any(!nzchar(z))) stop("Invalid gene symbol")
  unique(z)
})
names(shared) <- p
selected <- sort(intersect(shared[[1]],shared[[2]]))
expected <- sort(c("ETFDH","HADHB","ACO2","ECH1","PDHB","DLD","MDH1","DLST","SDHD","SUCLG1","FH","PDHA1","MDH2","RETSAT","DECR1","ACAA1"))
cat("Shared OXPHOS genes:",length(shared[[1]]),"\n")
cat("Shared fatty-acid-metabolism genes:",length(shared[[2]]),"\n")
cat("Four-way intersection:",length(selected),"genes\n")
print(selected)
cat("Missing relative to Table 2:",paste(setdiff(expected,selected),collapse=", "),"\n")
cat("Unexpected relative to Table 2:",paste(setdiff(selected,expected),collapse=", "),"\n")
if (!identical(selected,expected)) stop("FAILED: intersection does not exactly match the manuscript's 16 genes")
cat("PASS: exact 16-gene membership matches Table 2.\n")
cat("NOTE: Differential-expression FDR/logFC verification is a separate provenance step.\n")
